'use strict';
/* V11 M2 acceptance. All suggestions are generated by the existing local advisor
 * in Chromium; no model transport and no fabricated authorship scores.
 */
const assert=require('node:assert/strict');
const puppeteer=require('puppeteer-core');
const {serve,chrome}=require('../pdf-browser.test.js');
const en='teh report was recieved at the site. The measured strength was 25 MPa [12].';
const ar='هاذا تعبير محلي مكتوب بعناية، لاكن التقرير يحتاج مراجعة.';
async function setText(page,text){
 await page.$eval('#source',(el,s)=>{el.value=s;el.dispatchEvent(new Event('input',{bubbles:true}));},text);
}
async function indexOf(page,word){
 return page.$$eval('#tisV11SuggestionList li[data-review-index]',(items,needle)=>{
  const hit=items.find(el=>el.querySelector('.tis-v11-original')?.textContent.includes(needle));
  return hit?.dataset.reviewIndex??null;
 },word);
}
const sel=(index,cl)=>'[data-review-index="'+index+'"] .tis-v11-'+cl;
async function openPreview(page,index){
 await page.focus(sel(index,'preview-toggle'));await page.keyboard.press('Enter');
 assert.equal(await page.$eval(sel(index,'preview-toggle'),el=>el.getAttribute('aria-expanded')),'true');
 assert.equal(await page.$eval('#tisV11Preview'+index,el=>el.hidden),false);
}
async function run(){
 const server=serve();await new Promise(ok=>server.listen(0,'127.0.0.1',ok));
 const browser=await puppeteer.launch({headless:true,executablePath:chrome,args:['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']});
 const errors=[],outside=[],shots=process.env.TIS_SCREENSHOT_DIR;
 if(shots)require('node:fs').mkdirSync(shots,{recursive:true});
 const capture=async(page,name)=>{if(shots)await page.screenshot({path:require('node:path').join(shots,name+'.png'),fullPage:true});};
 try{
  const page=await browser.newPage();
  page.on('pageerror',e=>errors.push(e.message));
  page.on('request',r=>{
   const u=new URL(r.url());
   if(u.hostname!=='127.0.0.1'||/ai-runtime\.html/.test(u.pathname))outside.push(u.href);
  });
  await page.setViewport({width:1440,height:900});
  await page.goto('http://127.0.0.1:'+server.address().port+'/?v11preview=1',{waitUntil:'load'});
  await setText(page,en);
  await page.click('#scanAI');
  assert.equal(await page.evaluate(()=>document.body.dataset.v10Screen),'guided-review');
  const rev=await page.evaluate(()=>window.TISAnalysisApp.session.read().revision);
  let index=await indexOf(page,'teh');
  assert(index!==null,'Local advisor should expose the exact typo source');
  assert.equal(await page.$eval(sel(index,'apply'),el=>el.disabled),true,'Apply must require an explicit preview');
  assert.equal(await page.$eval('#tisV11Undo',el=>el.disabled),true,'No unrelated undo history is exposed');
  await openPreview(page,index);
  assert.equal(await page.$eval(sel(index,'apply'),el=>el.disabled),false);
  assert.match(await page.$eval('#tisV11Preview'+index,el=>el.textContent),/\bthe\b/);
  assert.equal(await page.$eval('#source',el=>el.value),en,'Preview must never change source');
  assert.equal(await page.evaluate(()=>window.TISAnalysisApp.session.read().revision),rev);
  await capture(page,'v11-m2-before-apply-en');
  await page.focus(sel(index,'apply'));await page.keyboard.press('Enter');
  const first=await page.evaluate(()=>({
   source:window.TISAnalysisApp.session.read().text,
   value:document.getElementById('source').value,
   revision:window.TISAnalysisApp.session.read().revision,
   view:document.body.dataset.v10Screen,
   undo:window.TISWorkspaceV11.reviewState().undoAvailable,
   focus:document.activeElement.id,
   report:document.getElementById('tisV11Status').textContent
  }));
  assert.match(first.source,/^the report was recieved/);
  assert.equal(first.source,first.value);
  assert.equal(first.revision,rev+1);
  assert.equal(first.view,'guided-review');
  assert.equal(first.undo,true);
  assert.equal(first.focus,'tisV11Undo');
  assert.match(first.report,/applied/i);
  assert.match(first.source,/25 MPa \[12\]/,'Protected measurement and citation must remain unchanged');
  await capture(page,'v11-m2-applied-en');
  index=await indexOf(page,'recieved');
  assert(index!==null,'Remaining suggestion must be recomputed against the new revision');
  assert.equal(await page.$eval(sel(index,'apply'),el=>el.disabled),true);
  await openPreview(page,index);
  await page.click(sel(index,'apply'));
  assert.match(await page.$eval('#source',e=>e.value),/^the report was received/);
  assert.equal(await page.evaluate(()=>window.TISAnalysisApp.session.read().revision),rev+2);
  await page.focus('#tisV11Undo');await page.keyboard.press('Enter');
  assert.match(await page.$eval('#source',e=>e.value),/^the report was recieved/);
  assert.equal(await page.$eval('#tisV11Undo',e=>e.disabled),false);
  await page.click('#tisV11Undo');
  assert.equal(await page.$eval('#source',e=>e.value),en,'Two explicit undo actions must restore the exact original');
  assert.equal(await page.$eval('#tisV11Undo',e=>e.disabled),true);
  assert.equal(await page.evaluate(()=>window.TISWorkspaceV11.reviewState().undoAvailable),false);
  console.log('PASS V11 M2 EN preview-first, exact revisioned apply, recomputation, two undos and fact preservation');

  // Dismissing must never edit the source, and must only affect this revision.
  index=await indexOf(page,'teh');
  assert(index!==null);
  const oldId=await page.$eval('[data-review-index="'+index+'"]',e=>e.dataset.suggestionId);
  const beforeCount=await page.evaluate(()=>window.TISWorkspaceV11.reviewState().suggestions);
  await page.click(sel(index,'dismiss'));
  assert.equal(await page.evaluate(()=>window.TISWorkspaceV11.reviewState().suggestions),beforeCount-1);
  assert.equal(await page.$eval('#source',e=>e.value),en);
  assert.equal(await page.evaluate(id=>window.TISAnalysisApp.review.getSuggestions().some(s=>s.id===id),oldId),false);
  console.log('PASS V11 M2 explicit dismiss stays local to the current revision and never edits source');

  // An external equal-length change must invalidate prior review and undo.
  await page.click('#tisV11Edit');
  await setText(page,en.replace('site','room'));
  await page.click('#scanAI');
  index=await indexOf(page,'teh');assert(index!==null);
  await openPreview(page,index);
  const liveId=await page.$eval('[data-review-index="'+index+'"]',e=>e.dataset.suggestionId);
  const afterPreview=await page.$eval('#source',e=>e.value);
  await page.evaluate(t=>{
   const app=window.TISAnalysisApp;app.session.replaceText(t,'paste');
   const source=document.getElementById('source');source.value=t;
   source.dispatchEvent(new Event('input',{bubbles:true}));
  },afterPreview.replace('room','site'));
  assert.equal(await page.evaluate(()=>document.body.dataset.v10Screen),'input');
  assert.equal(await page.evaluate(()=>window.TISWorkspaceV11.reviewState().revision),null);
  assert.equal(await page.$eval('#tisV11Undo',e=>e.disabled),true);
  const stale=await page.evaluate(id=>window.TISAnalysisApp.review.apply(id),liveId);
  assert.equal(stale.applied,false,'Previously reviewed revision may never apply after an external edit');
  assert.equal(await page.$eval('#source',e=>e.value),en);
  console.log('PASS V11 M2 equal-length stale revision rejected and old UI closed');

  // DOCX remains read-only even when the suggestion has a real replacement.
  const word=await browser.newPage();
  word.on('pageerror',e=>errors.push(e.message));
  try{
   await word.goto('http://127.0.0.1:'+server.address().port+'/?v11preview=1',{waitUntil:'load'});
   await word.evaluate(text=>{
    const app=window.TISAnalysisApp;app.session.replaceText(text,'docx');
    const source=document.getElementById('source');source.value=text;
    source.dispatchEvent(new Event('input',{bubbles:true}));
   },en);
   await word.click('#scanAI');
   assert.equal(await word.evaluate(()=>window.TISAnalysisApp.session.read().sourceKind),'docx');
   const idx=await indexOf(word,'teh');assert(idx!==null);
   await openPreview(word,idx);
   assert.equal(await word.$eval(sel(idx,'apply'),e=>e.disabled),true);
   assert.equal(await word.$eval('#tisV11DocxNote',e=>e.hidden),false);
   assert.match(await word.$eval('#tisV11Preview'+idx,e=>e.textContent),/read-only/i);
   assert.equal(await word.$eval('#source',e=>e.value),en);
   await capture(word,'v11-m2-docx-readonly');
  }finally{await word.close();}
  console.log('PASS V11 M2 Word source is read-only even after safe preview');

  const arabic=await browser.newPage();
  arabic.on('pageerror',e=>errors.push(e.message));
  try{
   await arabic.setViewport({width:390,height:844});
   await arabic.goto('http://127.0.0.1:'+server.address().port+'/?v11preview=1',{waitUntil:'load'});
   await arabic.click('#language');
   await setText(arabic,ar);
   await arabic.click('#scanAI');
   const idx=await indexOf(arabic,'هاذا');assert(idx!==null);
   assert.equal(await arabic.$eval(sel(idx,'apply'),e=>e.disabled),true,
    'Arabic dialect suggestion cannot be automatically replaced');
   await openPreview(arabic,idx);
   assert.equal(await arabic.$eval(sel(idx,'apply'),e=>e.disabled),true);
   const note=await arabic.$eval('#tisV11Preview'+idx,e=>e.textContent);
   assert.match(note,/مراجعة|صياغة/u);
   assert.equal(await arabic.$eval('#source',e=>e.value),ar);
   assert((await arabic.evaluate(()=>document.documentElement.scrollWidth-innerWidth))<=8);
   await capture(arabic,'v11-m2-arabic-manual-mobile');
   // Re-translate open preview with the underlying source unchanged.
   await arabic.click('#language');
   await arabic.waitForFunction(()=>document.getElementById('tisV11Undo').textContent==='Undo last correction');
   assert.equal(await arabic.evaluate(()=>window.TISWorkspaceV11.reviewState().previewOpen),true);
   assert.equal(await arabic.$eval('#source',e=>e.value),ar);
   console.log('PASS V11 M2 AR/RTL manual-only advice, localized preview and no horizontal scroll');
  }finally{await arabic.close();}
  assert.deepEqual(outside,[],'Local review must not call external model services');
  assert.deepEqual(errors,[],'No Chromium execution errors');
  console.log('PASS V11 M2 all revisioned apply/undo/manual/DOCX/privacy gates');
 }finally{await browser.close();await new Promise(ok=>server.close(ok));}
}
run().catch(e=>{console.error(e);process.exitCode=1;});
